(() => {
'use strict';
const D=window.GOODFOLK, $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2,minimumFractionDigits:0}).format(v);
const paths={arrow:'M4 12h16M14 6l6 6-6 6',chevron:'m9 5 7 7-7 7',back:'M20 12H4m6-6-6 6 6 6',search:'M21 21l-5-5M18 10.5a7.5 7.5 0 1 1-15 0 7.5 7.5 0 0 1 15 0',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',home:'m3 10 9-7 9 7M5 9v12h14V9M9 21v-8h6v8',tool:'M14 5a6 6 0 0 0-7 8L2 18a3 3 0 0 0 4 4l5-5a6 6 0 0 0 8-7l-4 4-5-5 4-4',truck:'M1 5h14v13H1ZM15 9h4l4 5v4h-8M7 18a2 2 0 1 1-4 0 2 2 0 0 1 4 0M21 18a2 2 0 1 1-4 0 2 2 0 0 1 4 0',leaf:'M20 3C5 1 2 8 5 15s17 5 15-12ZM4 21 16 9M8 17v-6m0 6h6',paw:'M12 12c-3 0-7 5-6 8 1 3 4 0 6 0s5 3 6 0c1-3-3-8-6-8ZM9 5c0 2-1 3-2 3S5 7 5 5s1-3 2-3 2 1 2 3ZM18 5c0 2-1 3-2 3s-2-1-2-3 1-3 2-3 2 1 2 3ZM5 11c0 2-1 3-2 3s-2-1-2-3 1-3 2-3 2 1 2 3ZM23 11c0 2-1 3-2 3s-2-1-2-3 1-3 2-3 2 1 2 3',bag:'M5 7h14l2 14H3L5 7ZM8 8V6a4 4 0 0 1 8 0v2',camera:'M3 6h4l2-3h6l2 3h4v15H3ZM16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0',laptop:'M4 3h16v14H4ZM1 21l3-4h16l3 4H1Z',grid:'M3 3h6v6H3ZM15 3h6v6h-6ZM3 15h6v6H3ZM15 15h6v6h-6Z',check:'m5 12 4 4L19 6',shield:'M12 2 3 6v6c0 6 9 10 9 10s9-4 9-10V6l-9-4Zm-5 9 3 3 6-6',clock:'M22 12A10 10 0 1 1 2 12a10 10 0 0 1 20 0ZM12 6v6l4 3',chat:'M21 11a9 9 0 0 1-9 9H3v-9a9 9 0 0 1 18 0ZM7 10h10M7 14h6',calendar:'M4 5h16v17H4ZM8 2v6M16 2v6M4 11h16',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 22v-3a8 8 0 0 1 16 0v3',close:'m6 6 12 12M6 18 18 6',menu:'M3 6h18M3 12h18M3 18h18',sun:'M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM12 1v3M12 20v3M1 12h3M20 12h3M4 4l2 2M18 18l2 2M20 4l-2 2M6 18l-2 2',briefcase:'M3 7h18v14H3ZM8 7V3h8v4M3 12c6 4 12 4 18 0M10 12h4v4h-4Z',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8ZM3 6l3-3 3 2 3-3 3 3 3-2 3 3-2 3 3 3-3 3 2 3-3 3-3-2-3 3-3-3-3 2-3-3 2-3-3-3 3-3-2-3Z',map:'m2 5 6-3 8 3 6-3v17l-6 3-8-3-6 3V5Zm6-3v17m8-14v17',send:'m3 3 19 9-19 9 3-9-3-9ZM6 12h16',repeat:'m17 2 4 4-4 4M3 11V8a2 2 0 0 1 2-2h16M7 22l-4-4 4-4m14-1v3a2 2 0 0 1-2 2H3',plus:'M12 4v16M4 12h16',star:'m12 2 3 6 7 1-5 5 1 8-6-4-6 4 1-8-5-5 7-1 3-6',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7',wallet:'M3 5h17v16H3V5Zm0 0 14-3v3m5 7h-7v5h7v-5',list:'M8 5h13M8 12h13M8 19h13M3 5h.1M3 12h.1M3 19h.1'};
const icon=(n,c='')=>`<svg class="icon ${c}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.spark}"/></svg>`;
const flower=`<svg class="brand-flower" viewBox="0 0 30 30" fill="currentColor" aria-hidden="true"><path d="M13 1h4l1 9 7-6 3 3-7 7 9 1v4l-9 1 6 6-3 3-7-7-1 8h-4l-1-9-7 6-3-3 7-7-8-1v-4l9-1-6-7 3-3 7 7z"/></svg>`;
const brand=`${flower}<span>goodfolk<span class="brand-dot">.</span></span>`;
const cat=id=>D.categories.find(c=>c.id===id)||D.categories[0];
const pro=id=>D.pros.find(p=>p.id===id);
const avatar=(p,extra='')=>`<div class="avatar ${extra}" style="background:${p.color||'#e0e3d4'}">${esc(p.initials||'JT')}</div>`;
const rating=p=>`<div class="star">★ <span>${p.rating.toFixed(2)}</span> <small>(${p.reviews} reviews)</small></div>`;
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const addDate=n=>{const d=new Date();d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const dateLabel=d=>new Date(`${d}T12:00:00`).toLocaleDateString('en-US',{month:'short',day:'numeric',weekday:'short'});
const uid=()=>`gf${Date.now().toString(36)}${Math.random().toString(36).slice(2,7)}`;
const baseState={saved:[],bookings:[],messages:{},account:{name:'JT',location:'Austin, TX',zip:'78702',area:'East Austin',email:'',updates:false},provider:{name:'',category:'handy',rate:48,bio:'',radius:10,days:[1,2,3,4,5],start:'09:00',end:'17:00',applied:false,accepted:[],hidden:[]},reviews:[]};
let saved={};try{saved=JSON.parse(localStorage.getItem('goodfolk.v1')||'{}')}catch(e){}
const state={...baseState,...saved,account:{...baseState.account,...saved.account},provider:{...baseState.provider,...saved.provider}};
let storageWorks=true;
const persist=()=>{try{localStorage.setItem('goodfolk.v1',JSON.stringify(state))}catch(e){storageWorks=false;toast('Your browser could not save this change. It will last for this visit.')}};
let view='home',currentPro='',query='',category='all',maxPrice=0,available=false,sort='recommended',showMap=false,bookingTab='upcoming',providerTab='requests',chatId='',modalState=null,focusReturn=null,toastTimer;
const nav=(route)=>{if(location.hash.slice(1)===route){render();window.scrollTo(0,0)}else location.hash=route};
const toast=text=>{clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800)};
const button=(label,action,cls='btn',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const img=(name,alt,cls='',lazy=true)=>`<img class="${cls}" src="assets/${name}" alt="${esc(alt)}" ${lazy?'loading="lazy"':''}>`;
function header(){const initials=state.account.name.trim().split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase()||'JT';return `<div class="demo-bar">A little look at what’s possible. Sample people and prices. ${button('About this preview','preview','')}</div><header class="site-header"><div class="container header-inner"><a class="brand" href="#home" aria-label="Goodfolk home">${brand}</a><nav class="nav-main" aria-label="Main navigation"><a href="#explore" class="${['home','explore','directory','profile'].includes(view)?'active':''}">Find help</a><a href="#bookings" class="${view==='bookings'?'active':''}">My bookings</a><a href="#messages" class="${view==='messages'?'active':''}">Messages</a><a href="#saved" class="${view==='saved'?'active':''}">Your people</a></nav><div class="header-actions">${button(`${icon('pin')}<span>Austin, TX</span>`,'location','location-button')}<a class="earn-link" href="#work">Become a pro</a><a href="#account" class="avatar" aria-label="Account settings">${esc(initials)}</a></div></div></header>`}
function footer(){return `<footer class="footer"><div class="container"><div class="footer-main"><div><a href="#home" class="brand">${brand}</a><p>Good people make life a little easier.<br>Your kind of help, right around the corner.</p></div><div class="footer-links"><a href="#how">How it works</a><a href="#trust">Our approach</a><a href="#work">For the goodfolk</a><a href="#vision">The bigger picture</a></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Goodfolk. A working idea by JT.</span><span>Product preview. No real bookings, messages, or payments.</span>${button('Photo credits','credits','text-link')}</div></div></footer><nav class="mobile-nav" aria-label="Mobile navigation">${[['home','search','Explore'],['bookings','calendar','Bookings'],['messages','chat','Messages'],['saved','heart','Your people'],['work','briefcase','For pros']].map(([v,i,l])=>`<a href="#${v}" class="${view===v||(v==='home'&&['explore','directory','profile'].includes(view))?'active':''}">${icon(i)}${l}</a>`).join('')}</nav>`}
function rail(){return `<div class="category-rail" aria-label="Service categories">${D.categories.map(c=>button(`${icon(c.icon)}<span>${c.name}</span>`,'category',`category-item ${category===c.id&&view==='explore'?'active':''}`,`data-id="${c.id}"`)).join('')}</div>`}
function searchForm(placeholder='What could you use a hand with?'){return `<form class="search-composer ${view==='explore'?'page-search':''}" data-form="search">${icon('search')}<label for="service-search" class="sr-only">Search services</label><input id="service-search" name="query" value="${esc(query)}" placeholder="${placeholder}" autocomplete="off"><button aria-label="Find services">${icon('arrow')}</button></form>`}
function home(){return `<div class="container"><section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="status-dot"></span> A little help. A lot more life.</div><h1>Life happens.<br><em>Goodfolk help.</em></h1><p class="intro">Find the right people for whatever’s on your list.<br>More done. Less to do. More time for you.</p>${searchForm()}<div class="quick-links"><span>Try</span>${['House cleaning','Furniture assembly','Moving help'].map(x=>button(x,'service','',`data-value="${x}"`)).join('')}</div><div class="hero-note">${icon('pin')}Thoughtfully local. Starting with Austin.</div></div><div class="hero-visual">${img('hero.jpg','Craftsperson bringing care and attention to their work','hero-main',false)}${img('garden.jpg','Hands tending to a green garden','hero-side',false)}<div class="hero-sticker">${icon('sun')}<span>Good people.<br>Better days.</span></div><div class="hero-caption"><span class="mini-sun">✳</span><div><b>People make the difference.</b><small>Find your kind of goodfolk.</small></div></div></div></section>${rail()}<section class="section"><div class="section-head"><div><h2>Small tasks. <em>Big relief.</em></h2><p>For the things you need done, and the life you want to live.</p></div><a class="text-link" href="#directory">Explore all services ${icon('arrow')}</a></div><div class="service-grid">${['home','handy','moving','outdoors'].map((id,i)=>{const c=cat(id);return button(`<div class="service-photo">${img(c.image,c.name+' service')}<span class="label">${['Make room to relax','Finally, all together','Your next chapter','A little fresh air'][i]}</span></div><h3>${c.name}${icon('arrow')}</h3><p>${c.intro}</p>`,'category','service-tile',`data-id="${id}"`)}).join('')}</div></section></div><div class="soft-band"><div class="container promise-row">${[['user','People, not endless listings','Get to know the person behind the work.'],['wallet','Clear before you commit','See the scope, time, and price together.'],['chat','Everything in one place','Keep the details with the conversation.']].map(([i,h,p])=>`<div class="promise">${icon(i)}<div><b>${h}</b><small>${p}</small></div></div>`).join('')}</div></div><div class="container"><section class="section"><div class="section-head"><div><div class="eyebrow" style="margin-bottom:13px">Meet the neighborhood</div><h2>Your next <em>go to person.</em></h2><p>A few of the friendly faces in our Austin preview.</p></div><a class="text-link" href="#explore">Meet everyone ${icon('arrow')}</a></div><div class="people-grid">${[D.pros[0],D.pros[1],D.pros[4]].map(p=>`<article class="person-preview"><div class="person-top">${avatar(p)}<div><a href="#profile/${p.id}" class="person-name">${p.name}</a>${rating(p)}</div><button class="save-heart ${state.saved.includes(p.id)?'saved':''}" data-action="save" data-id="${p.id}" aria-label="${state.saved.includes(p.id)?'Unsave':'Save'} ${p.name}" style="margin:0 0 0 auto">${icon('heart')}</button></div><p class="person-description">${p.title} ${p.area}.</p><div class="person-bottom"><span>${money(p.rate)} / hour <span class="tag" style="margin-left:7px">${cat(p.category).name}</span></span><a href="#profile/${p.id}" class="text-link">Meet ${p.name.split(' ')[0]} ${icon('arrow')}</a></div></article>`).join('')}</div></section><section class="story-banner"><div class="story-copy"><div class="eyebrow">For the goodfolk</div><h2>Good at something?<br><em>Make it your thing.</em></h2><p>Your skills deserve a neighborhood. Find work that fits your life, set your own rate, and build something that’s yours.</p><a class="btn light" href="#work">Find your next opportunity ${icon('arrow')}</a></div>${img('interior.jpg','A warm, thoughtfully cared for home')}</section></div>`}
function normalizeSearch(q){const t=q.toLowerCase();const synonyms={couch:'moving',sofa:'moving',move:'moving',clean:'home',cleaner:'home',cleaning:'home',assemble:'handy',assembly:'handy',handyman:'handy',repair:'handy',mount:'handy',mow:'outdoors',lawn:'outdoors',garden:'outdoors',dog:'pets',cat:'pets',pet:'pets',grocery:'errands',groceries:'errands',photographer:'creative',photo:'creative',wifi:'tech',computer:'tech'};return Object.entries(synonyms).find(([k])=>new RegExp(`\\b${k}\\w*`).test(t))?.[1]}
function matching(){let out=D.pros.filter(p=>(category==='all'||p.category===category)&&(!available||p.today)&&(!maxPrice||p.rate<=maxPrice));if(query.trim()){const exact=D.categories.flatMap(c=>c.sub).find(s=>s.toLowerCase()===query.trim().toLowerCase());const normalized=normalizeSearch(query);const tokens=query.toLowerCase().trim().split(/\s+/).filter(w=>!['i','a','an','the','need','help','with','my','to','someone','please','tomorrow','today','for'].includes(w));out=out.filter(p=>exact?p.skills.includes(exact):(normalized&&p.category===normalized)||tokens.length===0||tokens.every(t=>`${p.name} ${p.area} ${p.bio} ${p.skills.join(' ')} ${cat(p.category).name}`.toLowerCase().includes(t)))}return out.sort((a,b)=>sort==='price'?a.rate-b.rate:sort==='rating'?b.rating-a.rating:sort==='distance'?a.distance-b.distance:((a.today?0:1)-(b.today?0:1))||a.distance-b.distance)}
function proRow(p){return `<article class="pro-row"><a href="#profile/${p.id}" class="pro-image" aria-label="View ${p.name}">${img(p.image,p.skills[0])}${avatar(p)}</a><div><div class="pro-title"><button data-action="profile" data-id="${p.id}">${p.name}</button>${p.today?'<span class="tag">Today</span>':''}</div>${rating(p)}<div class="pro-sub">${p.area} · ${p.distance} mi away · ${p.jobs} sample jobs</div><p>${p.title} ${p.fit}.</p><div class="pro-skills">${p.skills.slice(0,3).map(s=>`<span>${s}</span>`).join('')}</div></div><div class="pro-price"><button class="save-heart ${state.saved.includes(p.id)?'saved':''}" data-action="save" data-id="${p.id}" aria-label="${state.saved.includes(p.id)?'Unsave':'Save'} ${p.name}">${icon('heart')}</button><div class="price-value">${money(p.rate)} <small>/ hour</small></div><div class="price-detail">Plus 12% service fee</div>${button(`Meet ${p.name.split(' ')[0]}`,'profile','btn',`data-id="${p.id}"`)}</div></article>`}
function mapView(results){const positions=[[110,250],[252,322],[265,112],[135,117],[200,215],[332,203],[130,339],[350,88],[53,329],[75,80]];return `<aside class="map-panel"><svg class="map-art" viewBox="0 0 440 430" role="group" aria-label="Illustrative Austin neighborhood map showing sample providers"><rect width="440" height="430" fill="#e8ebdf"/><g fill="#dce3cb"><path d="M5 18h123v74H5zM282 15h143v89H282zM15 203h68v97H15zM279 267h144v147H279zM135 152h69v61h-69z"/></g><g stroke="#f8f7ee" stroke-width="13" fill="none"><path d="M0 125 440 170M-20 216 435 254M39 0l25 430M145 0l17 430M265 0l-18 430M380 0l-33 430M0 51l440 22M0 348l440 32"/></g><g stroke="#d0d6c3" stroke-width="2" fill="none"><path d="M0 290 440 350M205 0l-8 430M315 0l-17 430"/></g><path d="M-30 292C90 250 171 374 291 269s142-38 179-60" fill="none" stroke="#b3ced0" stroke-width="27"/><g fill="#869181" font-family="Arial" font-size="10" letter-spacing="2"><text x="62" y="193">EAST AUSTIN</text><text x="229" y="62">HYDE PARK</text><text x="250" y="394">SOUTH LAMAR</text><text x="191" y="294" transform="rotate(-15 191 294)">LADY BIRD LAKE</text></g>${results.slice(0,10).map((p,i)=>{const [x,y]=positions[i];return `<g class="map-pin" data-action="profile" data-id="${p.id}" tabindex="0" role="button" aria-label="View ${p.name}, ${money(p.rate)} per hour" transform="translate(${x},${y})"><rect x="-23" y="-16" width="46" height="29" rx="14" fill="#2f4638"/><text text-anchor="middle" y="3" font-family="Arial" font-size="11" fill="white">$${p.rate}</text></g>`}).join('')}<circle cx="206" cy="225" r="11" fill="#cc5138" opacity=".18"/><circle cx="206" cy="225" r="5" fill="#cc5138" stroke="white" stroke-width="2"/></svg><div class="map-caption"><span>${icon('pin')} Austin neighborhoods</span><span>${results.length} sample matches</span></div><div class="map-note">Illustrative locations. Not a live map.</div></aside>`}
function explore(){const results=matching();return `<div class="container space-bottom"><div class="page-top"><div class="eyebrow"><span class="status-dot"></span> Your neighborhood, ready to help</div><h1 style="margin-top:17px">${category==='all'?'Find your kind of help.':esc(cat(category).name)+', handled.'}</h1>${searchForm('Try “help moving a couch tomorrow”')}</div>${rail()}<div class="filter-bar">${button(`${icon('clock')} Available today`,'today',`filter-pill ${available?'active':''}`)}<label class="sr-only" for="price-filter">Hourly budget</label><select id="price-filter" data-filter="price"><option value="0">Any hourly budget</option>${[30,40,50,60].map(n=>`<option value="${n}" ${maxPrice===n?'selected':''}>Up to $${n} / hour</option>`).join('')}</select><label class="sr-only" for="sort-filter">Sort people</label><select id="sort-filter" data-filter="sort">${[['recommended','Recommended'],['price','Lowest rate'],['rating','Highest rating'],['distance','Closest first']].map(([v,l])=>`<option value="${v}" ${sort===v?'selected':''}>${l}</option>`).join('')}</select>${button('Clear filters','clear-filters','text-link')}<div class="filter-spacer"></div>${button(`${icon(showMap?'list':'map')} ${showMap?'List only':'Show map'}`,'map','filter-pill')}</div><div class="result-meta"><span>${results.length} goodfolk ${query?`for “${esc(query)}”`:'in your Austin preview'}</span><span>Sample rates · 12% service fee added at booking</span></div><div class="results-layout ${showMap?'with-map':''}"><div>${results.length?results.map(proRow).join(''):`<div class="empty">${icon('search')}<h3>No matches just yet.</h3><p>Try a broader service, raise your hourly budget, or include people available another day.</p>${button('Reset your search','clear-all','btn')}</div>`}</div>${showMap?mapView(results):''}</div>${results.length?`<div class="notice">Looking for a bigger project? ${button('Tell us what you have in mind','quote','text-link')} and explore the estimate request flow.</div>`:''}</div>`}
function directory(){return `<div class="container space-bottom"><div class="page-top"><div class="eyebrow">Whatever’s on your list</div><h1 style="margin-top:18px">There’s goodfolk for that.</h1><p>Explore ${D.categories.reduce((a,c)=>a+c.sub.length,0)} ways to make a little more room in your day.</p></div><div class="directory-grid">${D.categories.filter(c=>c.id!=='all').map(c=>`<section class="directory-group"><h3>${icon(c.icon)}${c.name}</h3>${c.sub.map(s=>button(s+' →','service','',`data-value="${s}"`)).join('')}</section>`).join('')}</div><div class="soft-band" style="padding:25px;margin-top:20px"><h3 style="font-size:23px">Something a little different?</h3><p style="font-size:13px;margin:12px 0 18px">Describe the project and build an estimate request with the details that matter.</p>${button('Request an estimate','quote','btn')}</div></div>`}
function profile(){const p=pro(currentPro);if(!p)return notFound();return `<div class="container"><div class="breadcrumb"><a href="#explore">Find help</a>${icon('chevron')}<span>${cat(p.category).name}</span>${icon('chevron')}<span>${p.name}</span></div><section class="profile-hero"><div class="profile-intro"><div class="person-top">${avatar(p,'large')}<div><div class="eyebrow">Meet ${p.name.split(' ')[0]}</div><p style="font-size:12px;margin-top:6px">${p.area} · ${p.distance} miles away</p></div>${button(icon('heart'),'save',`save-heart ${state.saved.includes(p.id)?'saved':''}`,`data-id="${p.id}" aria-label="Save ${p.name}" style="margin-left:auto"`)}</div><h1>${p.title}</h1><p>${p.bio}</p>${rating(p)}<div class="profile-facts"><div><b>${p.years}</b><small>Years of experience</small></div><div><b>${p.jobs}</b><small>Sample completed jobs</small></div><div><b>${p.today?'Today':'Tomorrow'}</b><small>Preview availability</small></div></div></div>${img(p.image,p.skills[0]+' work example','profile-photo',false)}</section><div class="profile-body"><div><section class="profile-section"><h3>A few things I can help with.</h3><div class="skill-list">${p.skills.map(s=>button(s,'book-service','',`data-id="${p.id}" data-value="${s}"`)).join('')}</div></section><section class="profile-section"><h3>The little details.</h3><p style="font-size:13px;line-height:1.9">${p.fit}. Your task notes, timing, and agreed scope stay together in the booking. Ask about supplies, parking, and access before the visit so everyone knows what to expect.</p><div class="inline-actions">${button(`${icon('chat')} Start a conversation`,'message','btn soft',`data-id="${p.id}"`)}${button('Request an estimate','quote','text-link',`data-id="${p.id}"`)}</div></section><section class="profile-section"><div class="subtle-label">A sample neighborhood review</div><p class="review-quote">“${p.quote}”</p><div class="review-credit">${p.reviewer} · ${p.skills[0]} · ★★★★★</div></section><p class="notice">This is an illustrative profile. Names, ratings, experience, and availability are sample data. Photography illustrates the service.</p></div><aside class="booking-aside"><div class="eyebrow" style="margin-bottom:15px">A little help starts here</div><div class="price-value">${money(p.rate)} <small>/ hour</small></div><p>Choose your task and time. You’ll see the full estimate before confirming.</p><div class="date-strip">${[p.today?0:1,p.today?1:2,p.today?2:3].map((n,i)=>`<button class="date-chip ${i===0?'selected':''}" data-action="book-date" data-id="${p.id}" data-value="${addDate(n)}">${new Date(addDate(n)+'T12:00:00').toLocaleDateString('en-US',{weekday:'short'})}<b>${new Date(addDate(n)+'T12:00:00').getDate()}</b></button>`).join('')}</div>${button(`Choose a time ${icon('arrow')}`,'book','btn accent wide',`data-id="${p.id}"`)}<p class="notice">12% service fee shown at review. Materials are excluded unless agreed. Nothing is charged in this preview.</p></aside></div></div>`}
function savedPeople(){const people=D.pros.filter(p=>state.saved.includes(p.id));return `<div class="container space-bottom"><div class="page-top"><div class="eyebrow">Keep the good ones close</div><h1 style="margin-top:18px">Your people.</h1><p>One familiar place for the people you’d call again.</p></div>${people.length?people.map(proRow).join(''):`<div class="empty">${icon('heart')}<h3>Your circle starts with one good person.</h3><p>Tap the heart on anyone you like. Your saved people will be here when life needs a little help.</p><a class="btn" href="#explore">Find your first goodfolk ${icon('arrow')}</a></div>`}</div>`}
const isQuote=b=>b.budget!=null;
const bookingStatus=b=>b.status==='requested'?'Estimate requested':b.status==='completed'?'Completed':b.status==='canceled'?'Canceled':'Upcoming';
function bookingRow(b){const p=pro(b.proId);return `<article class="job-row">${p?avatar(p):`<div class="avatar">${icon('list')}</div>`}<div><span class="tag ${b.status==='requested'?'clay':b.status==='canceled'?'neutral':''}">${bookingStatus(b)} · Preview</span><h3>${esc(b.service)}</h3><p>${p?p.name+' · ':''}${dateLabel(b.date)}${b.time?' at '+b.time:''}</p><p style="margin-top:4px">${isQuote(b)?'Budget '+money(b.budget):money(b.total)+' estimated total'}${b.repeat&&b.repeat!=='Once'?' · '+b.repeat:''}</p></div><div class="job-row-actions">${button('View details','job','btn soft',`data-id="${b.id}"`)}${p?button(b.status==='completed'?'Book again':'Message',''+(b.status==='completed'?'rebook':'message'),'text-link',`data-id="${b.status==='completed'?b.id:p.id}"`):''}</div></article>`}
function bookings(){const jobs=state.bookings.filter(b=>bookingTab==='all'||(bookingTab==='upcoming'&&['upcoming','requested'].includes(b.status))||b.status===bookingTab);return `<div class="container space-bottom"><div class="page-top"><div class="page-heading"><div><div class="eyebrow">A little less on your mind</div><h1 style="margin-top:17px">Your bookings.</h1></div><a class="btn" href="#explore">Find more help ${icon('plus')}</a></div><div class="tabs">${[['upcoming','Upcoming'],['completed','Completed'],['canceled','Canceled'],['all','All bookings']].map(([v,t])=>button(t,'booking-tab',bookingTab===v?'active':'',`data-id="${v}"`)).join('')}</div></div>${jobs.length?jobs.slice().reverse().map(bookingRow).join(''):`<div class="empty">${icon('calendar')}<h3>${bookingTab==='upcoming'?'Good days are ahead.':'Nothing here yet.'}</h3><p>${bookingTab==='upcoming'?'Book your first preview task and you can manage it here, from the first details to the final thank you.':'When a booking moves here, its details and conversation stay together.'}</p><a class="btn" href="#explore">Explore your neighborhood ${icon('arrow')}</a></div>`}</div>`}
function ensureChat(id){if(!pro(id))return;if(!state.messages[id]){state.messages[id]=[{id:uid(),text:'This is your preview conversation. Use it to try sharing task details, questions, or a note before the visit.',from:'system',time:new Date().toISOString()}];persist()}chatId=id}
function messages(){const ids=Object.keys(state.messages).filter(id=>pro(id));if(!chatId&&ids.length)chatId=ids[0];const p=pro(chatId);return `<div class="container"><div class="page-top"><h1>Good conversations.</h1><p>Clear details make good work possible.</p></div>${ids.length?`<div class="inbox"><aside class="conversation-list" aria-label="Conversations">${ids.map(id=>{const u=pro(id),msgs=state.messages[id];return button(`${avatar(u)}<span><strong>${u.name}</strong><small>${esc(msgs[msgs.length-1]?.text||'Start a conversation')}</small></span>`,'chat',`conversation ${chatId===id?'active':''}`,`data-id="${id}"`)}).join('')}</aside><section class="chat-pane"><div class="chat-heading"><div><h3>${p?.name||'Choose a conversation'}</h3><small>Preview conversation · Messages stay in this browser</small></div>${p?button('View profile','profile','text-link',`data-id="${p.id}"`):''}</div><div class="chat-messages" id="chat-scroll">${(state.messages[chatId]||[]).map(m=>`<div class="chat-bubble ${m.from==='me'?'mine':''}">${esc(m.text)}<small>${m.from==='system'?'Goodfolk preview':esc(state.account.name)} · ${new Date(m.time).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})}</small></div>`).join('')}</div>${p?`<form class="chat-compose" data-form="chat"><label class="sr-only" for="message-input">Message</label><input id="message-input" name="message" placeholder="Share a detail or ask a question…" required maxlength="2000" autocomplete="off"><button class="btn">Save message ${icon('send')}</button></form><div class="chat-footnote">This tries the conversation flow. No person is contacted.</div>`:''}</section></div>`:`<div class="empty">${icon('chat')}<h3>Every good job starts with a hello.</h3><p>Start a conversation from a person’s profile or your booking. Everything stays together here.</p><a class="btn" href="#explore">Meet the goodfolk ${icon('arrow')}</a></div>`}</div>`}
function workspace(){const pv=state.provider;return `<div class="container"><div class="page-top"><div class="page-heading"><div><div class="eyebrow">For the goodfolk</div><h1 style="margin-top:17px">Make good work yours.</h1><p>Your skills. Your schedule. Your neighborhood.</p></div>${button(pv.applied?'Edit your profile':'Build your pro profile','provider-edit','btn accent')}</div></div><div class="workspace-layout"><aside><nav class="workspace-nav" aria-label="Provider navigation">${[['requests','briefcase','Opportunities'],['schedule','calendar','Your schedule'],['earnings','wallet','Your earnings'],['profile','user','Your profile']].map(([v,i,t])=>button(icon(i)+t,'provider-tab',pvTab(v),`data-id="${v}"`)).join('')}</nav><p class="workspace-note">Your workspace preview.<br>Sample requests let you explore the provider experience. No real customers are contacted.</p></aside><div>${providerTab==='requests'?`<div class="summary-strip"><div class="summary-stat"><b>${D.leads.filter(l=>!pv.hidden.includes(l.id)&&!pv.accepted.includes(l.id)).length}</b><span>Sample opportunities</span></div><div class="summary-stat"><b>${pv.accepted.length}</b><span>Accepted in preview</span></div><div class="summary-stat"><b>${money(pv.rate)}</b><span>Your hourly rate</span></div></div><div class="section-head" style="margin-top:30px"><div><h3>Around your corner.</h3><p style="font-size:12px">Try accepting a request or passing on one that doesn’t fit.</p></div></div>${D.leads.filter(l=>!pv.hidden.includes(l.id)&&!pv.accepted.includes(l.id)).map(l=>`<article class="lead-row"><div><div class="eyebrow">${l.distance} miles away · Sample request</div><h3>${l.service}</h3><p>${l.area} · ${l.when}</p><p style="margin-top:12px">${l.note}</p><div class="inline-actions">${button('Accept in preview','accept-lead','btn',`data-id="${l.id}"`)}${button('Pass for now','pass-lead','btn ghost',`data-id="${l.id}"`)}</div></div><div><div class="price-value">${money(l.budget)}</div><p style="font-size:10px;text-align:right">${l.hours} hours<br>Sample task budget</p></div></article>`).join('')||`<div class="empty">${icon('check')}<h3>You’re all caught up.</h3><p>Accepted preview work is in your schedule.</p>${button('Reset sample requests','reset-leads','btn soft')}</div>`}`:providerTab==='schedule'?`<h3 style="margin-top:22px">A schedule that works for you.</h3><p style="font-size:12px;margin-top:13px">Select the days you usually want to work.</p><div class="availability-grid">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((d,i)=>button(`${d}<span>${pv.days.includes(i)?'Available':'Rest day'}</span>`,'availability',`availability-day ${pv.days.includes(i)?'selected':''}`,`data-id="${i}" aria-pressed="${pv.days.includes(i)}"`)).join('')}</div><form data-form="availability" class="form-grid"><div class="field"><label for="start-time">Start time</label><input type="time" id="start-time" name="start" value="${pv.start}" required></div><div class="field"><label for="end-time">Finish time</label><input type="time" id="end-time" name="end" value="${pv.end}" required></div><div><button class="btn">Save working hours</button></div><p class="form-error" id="availability-error" role="alert"></p></form><h3 style="margin:35px 0 10px;font-size:23px">Your accepted work.</h3>${pv.accepted.length?D.leads.filter(l=>pv.accepted.includes(l.id)).map(l=>`<div class="lead-row"><div><span class="tag">Accepted in preview</span><h3>${l.service}</h3><p>${l.area} · ${l.when}</p></div>${button('Release task','release-lead','text-link',`data-id="${l.id}"`)}</div>`).join(''):`<p style="font-size:12px;margin:20px 0">Accept a sample opportunity to see it here.</p>`}`:providerTab==='earnings'?`<div class="summary-strip"><div class="summary-stat"><b>$0</b><span>Real earnings</span></div><div class="summary-stat"><b>${money(D.leads.filter(l=>pv.accepted.includes(l.id)).reduce((a,l)=>a+l.budget,0))}</b><span>Accepted sample task value</span></div><div class="summary-stat"><b>0</b><span>Payments processed</span></div></div><div class="reading-section"><h3>Keep the price clear.</h3><p>The proposed model lets providers set their hourly rate. Customers see a separate 12% service fee before confirming. Materials and scope changes need a separate agreement.</p><p style="margin-top:15px">The amounts here illustrate the idea. Payment processing, payouts, taxes, operating costs, and final pricing still need to be established before launch.</p></div><div class="reading-section"><h3>Try the numbers.</h3><form data-form="earnings"><div class="form-grid"><div class="field"><label for="calc-rate">Hourly rate</label><input type="number" name="rate" id="calc-rate" min="10" max="500" value="${pv.rate}" required></div><div class="field"><label for="calc-hours">Hours per week</label><input type="number" name="hours" id="calc-hours" min="1" max="80" value="20" required></div></div><button class="btn soft">Calculate gross task value</button><p id="earnings-output" class="notice" aria-live="polite">Illustration only. This is not an earnings promise.</p></form></div>`:providerProfile()}</div></div></div>`}
function pvTab(v){return providerTab===v?'active':''}
function providerProfile(){const p=state.provider;return `<div class="settings-form"><h3 style="margin-bottom:14px">A little about your good work.</h3><p style="font-size:12px;margin-bottom:27px">Create a profile draft and try the provider experience. This doesn’t publish a real listing.</p><form data-form="provider"><div class="field"><label for="pro-name">Your name</label><input id="pro-name" name="name" value="${esc(p.name)}" placeholder="What should people call you?" required maxlength="70"></div><div class="form-grid"><div class="field"><label for="pro-category">Your main service</label><select id="pro-category" name="category">${D.categories.filter(c=>c.id!=='all').map(c=>`<option value="${c.id}" ${p.category===c.id?'selected':''}>${c.name}</option>`).join('')}</select></div><div class="field"><label for="pro-rate">Your hourly rate</label><input id="pro-rate" name="rate" type="number" value="${p.rate}" min="10" max="500" required></div></div><div class="field"><label for="pro-bio">Tell people what you do well</label><textarea id="pro-bio" name="bio" placeholder="Your experience, approach, and the details you care about." maxlength="1500" required>${esc(p.bio)}</textarea></div><div class="field"><label for="pro-radius">How far would you like to travel?</label><select id="pro-radius" name="radius">${[5,10,15,20,30].map(n=>`<option value="${n}" ${p.radius===n?'selected':''}>Within ${n} miles</option>`).join('')}</select></div><button class="btn accent">Save your profile draft ${icon('arrow')}</button><p class="notice">Draft only. Identity checks, any required credentials, and provider onboarding are part of the future launch plan.</p></form></div>`}
function account(){return `<div class="container"><div class="page-top"><h1>Make yourself at home.</h1><p>A few details to make the experience feel like yours.</p></div><div class="settings-form"><form data-form="account"><h3 class="form-section-title">The basics.</h3><div class="form-grid"><div class="field"><label for="account-name">Name</label><input id="account-name" name="name" value="${esc(state.account.name)}" maxlength="70" required></div><div class="field"><label for="account-email">Email for your draft</label><input id="account-email" name="email" type="email" value="${esc(state.account.email)}" placeholder="you@example.com"><small>No email will be sent.</small></div></div><h3 class="form-section-title">Your neighborhood.</h3><div class="form-grid"><div class="field"><label for="account-area">Austin neighborhood</label><select id="account-area" name="area">${['East Austin','South Lamar','North Loop','Hyde Park','Cherrywood','Bouldin Creek','Mueller','Zilker','Crestview','Other Austin neighborhood'].map(a=>`<option ${state.account.area===a?'selected':''}>${a}</option>`).join('')}</select></div><div class="field"><label for="account-zip">ZIP code</label><input id="account-zip" name="zip" value="${esc(state.account.zip)}" inputmode="numeric" pattern="[0-9]{5}" maxlength="5" required></div></div><button class="btn">Save your details</button></form><div class="toggle-row"><div>Helpful booking reminders<small>Preference preview. No notifications are sent.</small></div><button class="toggle" role="switch" aria-checked="${state.account.updates}" aria-label="Helpful booking reminders" data-action="toggle-updates"></button></div><p class="notice">Your preview data stays in this browser. It does not sync between devices. Use sample details while exploring.</p>${button('Reset all preview activity','reset-preview','text-link text-danger','style="margin-top:25px"')}</div></div>`}
function how(){return `<div class="container space-bottom"><div class="page-top"><div class="eyebrow">A simple kind of useful</div><h1 style="margin-top:18px">Help should feel <em>easy.</em></h1><p>A clear path from “I should do that” to “that feels good.”</p></div><div class="steps-editorial">${[['01','Say what needs doing.','Choose a service or describe the task in your own words. Browse people by availability, location, experience, and price.'],['02','Find your kind of person.','Read a profile, compare the details, and talk through the work. Save the people you’d like to have in your corner.'],['03','Make a little more room.','Agree on the scope, pick a time, and review the total. Keep your booking and conversation together.']].map(([n,h,p])=>`<div class="step-editorial"><span class="number">${n}</span><h3>${h}</h3><p>${p}</p></div>`).join('')}</div><div class="reading-page"><div class="reading-section"><h3>One task or a bigger project?</h3><p>Defined tasks use an hourly estimate with an agreed duration. For a project that needs a conversation first, request an estimate and describe the budget, timing, and details. The preview shows both paths.</p></div>${[['Can I book the same person again?','Yes. Save someone to Your people, or choose Book again from a completed booking. The previous service and scope carry into a fresh booking for you to review.'],['What is included in the price?','The preview estimate includes the provider’s hourly rate multiplied by the time you choose, plus a clearly shown 12% service fee. Materials are excluded. This is proposed pricing, not a live offer.'],['Can I change my booking?','Yes. Open My bookings, choose View details, and reschedule or cancel an upcoming preview booking. The same booking record is updated.'],['What happens when the task is bigger than expected?','The intended launch model requires both sides to agree on added time, materials, or other scope changes before more work begins. The current preview records the original agreed scope.'],['Is Goodfolk available to hire from today?','This version is an interactive concept for Austin. People, prices, ratings, reviews, messages, and availability are illustrative. It does not hire a person, take payments, or send messages.']].map(([q,a])=>`<details class="faq-row"><summary>${q}</summary><p>${a}</p></details>`).join('')}<div class="inline-actions"><a href="#explore" class="btn">Find your kind of help ${icon('arrow')}</a>${button('Try an estimate request','quote','btn soft')}</div></div></div>`}
function trust(){return `<div class="container"><div class="page-top"><div class="eyebrow">Our approach</div><h1 style="margin-top:18px">Good work starts<br>with <em>good expectations.</em></h1></div><div class="reading-page"><p>A marketplace should make it easier to know who you are hiring, what you are agreeing to, and where to turn when something needs attention.</p>${[['Know the person.','Profiles are designed to bring experience, reviews, completed work, and communication into one place. The sample profiles here are not verified people. Before a real launch, identity and any service specific credentials need an established verification process.'],['Agree on the details.','Describe the task, choose the time, and review the price before confirming. Include access, stairs, supplies, pets, and anything else that helps someone prepare. Added work should always need fresh approval.'],['Keep a shared record.','Bookings and conversations belong together. A real service will need accountable support, clear cancellation terms, a fair review process, and a route for resolving problems. The preview lets you explore the core customer flow.'],['Care for both sides.','Providers should choose their rates and availability. Customers should see the complete proposed price. Any insurance, guarantees, screening, payment protection, or other promises must be in place before being advertised.'],['Stay thoughtful about personal details.','Use sample details in this concept. Activity is saved only in your current browser. The live product will need secure accounts, access controls, data retention rules, and a published privacy policy.']].map(([h,p])=>`<section class="reading-section"><h3>${h}</h3><p>${p}</p></section>`).join('')}<p class="notice">Goodfolk is not an emergency service. For an immediate emergency, contact the appropriate emergency service.</p></div></div>`}
function vision(){return `<div class="container space-bottom"><div class="page-top"><div class="eyebrow">The bigger picture · Working business concept</div><h1 style="margin-top:18px">A neighborhood<br>of <em>possibility.</em></h1><p>More than finding someone. A better way to make everyday life work.</p></div><div class="reading-page"><p>Goodfolk brings everyday local help into one calm, useful experience. The goal is to turn a scattered search into a lasting relationship with someone you would happily hire again.</p><section class="reading-section"><h3>Start with one city. Earn the next.</h3><p>Austin is the proposed first market. Start with a reliable group of providers across cleaning, assembly, moving help, and garden care. Grow neighborhood by neighborhood, measuring completed jobs, repeat bookings, cancellations, and customer satisfaction before expanding.</p></section><section class="reading-section"><h3>A model people can understand.</h3><p>The initial concept uses provider set rates and a visible 12% customer service fee. At a $100 task subtotal, the proposed fee is $12, giving a $112 customer estimate before any separately agreed materials or applicable taxes. This is a planning assumption. Processing costs, support, acquisition, insurance, and taxes must be modeled before final pricing is set.</p></section><section class="reading-section"><h3>Build for coming back.</h3><p>Saved people, recurring care, transparent scope, and simple repeat booking are central to the idea. The business should succeed when the customer finds someone worth calling again.</p></section></div><div class="plan-grid">${[['home','Everyday care','Regular cleaning, garden visits, pet care, and the small tasks that keep life moving.','home'],['truck','Life in motion','Moving, unpacking, assembly, and home setup collected around a new beginning.','moving'],['camera','Good times together','Photography, event setup, and a helping hand for a day worth remembering.','creative']].map(([i,h,p,c])=>`<div class="plan-item">${icon(i)}<h3>${h}</h3><p>${p}</p>${button('Explore these services '+icon('arrow'),'category','text-link',`data-id="${c}"`)}</div>`).join('')}</div><div class="reading-page"><section class="reading-section"><h3>What comes after this preview.</h3><p>Real customer and provider accounts, a shared database, identity and credential checks, actual availability, payment processing, provider payouts, support operations, and launch policies. The current product lets us refine the experience before connecting those live systems.</p></section><section class="reading-section"><h3>The launch questions worth answering.</h3><p>Which services get repeat bookings? How quickly can the right person accept a task? Do providers earn enough after their costs? Does the service fee cover the cost to acquire and support a booking? A focused pilot should answer these with real evidence before broad expansion.</p></section></div></div>`}
function notFound(){return `<div class="container empty"><h1 style="font-size:38px">Let’s find your way back.</h1><p style="margin-top:20px">That page isn’t in this neighborhood.</p><a href="#home" class="btn">Back to Goodfolk</a></div>`}
function render(){const renderers={home,explore,directory,profile,saved:savedPeople,bookings,messages,work:workspace,account,how,trust,vision};$('#app').innerHTML=header()+`<main id="main" tabindex="-1">${(renderers[view]||notFound)()}</main>`+footer();document.title=`${({home:'Your kind of help, nearby',explore:'Find help',profile:pro(currentPro)?.name,bookings:'Your bookings',messages:'Messages',saved:'Your people',work:'For the goodfolk',account:'Your account',directory:'Every service',how:'How it works',trust:'Our approach',vision:'The bigger picture'})[view]||'Welcome'} · Goodfolk`;if(view==='messages')scrollChat()}
function route(){const h=location.hash.slice(1)||'home';const parts=h.split('/');view=parts[0];if(view==='profile')currentPro=parts[1];if(view==='messages'&&parts[1])ensureChat(parts[1]);closeModal(false);render();window.scrollTo(0,0)}
function scrollChat(){const el=$('#chat-scroll');if(el)el.scrollTop=el.scrollHeight}
function openModal(title,body,small=false){if(!modalState)focusReturn=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${small?'small':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><h2 id="modal-title">${title}</h2>${button(icon('close'),'close-modal','icon-button','aria-label="Close dialog"')}</header><div class="modal-body">${body}</div></section></div>`;document.body.style.overflow='hidden';setTimeout(()=>{$('.modal [autofocus]')?.focus()||$('.modal button')?.focus()},20)}
function closeModal(restore=true){$('#modal-root').innerHTML='';document.body.style.overflow='';modalState=null;if(restore&&focusReturn?.isConnected)focusReturn.focus()}
function showPreview(){modalState={type:'preview'};openModal('A little look at the future.',`<p style="font-size:14px;line-height:1.8">Goodfolk is a working marketplace concept by JT. Explore the full customer journey and the provider workspace.</p><div class="reading-section" style="margin-top:24px"><h3 style="font-size:21px">What you can try</h3><p>Search services, filter and compare people, save favorites, make preview bookings, reschedule, write reviews, draft messages, and build a provider profile.</p></div><div class="reading-section"><h3 style="font-size:21px">A few things to know</h3><p>People, ratings, reviews, prices, and availability are sample data. Nothing is booked with a real person, sent, or charged. Your activity stays in this browser. Please use sample personal details.</p></div><a href="#vision" class="btn" data-action="close-link">Explore the business idea ${icon('arrow')}</a>`,true)}
function startBooking(id,service,date,previous){const p=pro(id);if(!p)return;focusReturn=document.activeElement;modalState={type:'booking',step:1,proId:id,draft:{service:service||p.skills[0],hours:previous?.hours||2,scope:previous?.scope||'',date:date||addDate(p.today?0:1),time:p.availability[0],address:'',repeat:previous?.repeat||'Once'}};bookingModal()}
function costs(d,p){const subtotal=Math.round(p.rate*Number(d.hours)*100)/100,fee=Math.round(subtotal*.12*100)/100;return {subtotal,fee,total:Math.round((subtotal+fee)*100)/100}}
function bookingSummary(p,d){const c=costs(d,p);return `<aside class="booking-summary"><div class="person-top">${avatar(p)}<div><h4>${p.name}</h4><p>${cat(p.category).name}</p></div></div><div class="cost-row"><span>${money(p.rate)} × ${d.hours} ${Number(d.hours)===1?'hour':'hours'}</span><span>${money(c.subtotal)}</span></div><div class="cost-row"><span>Service fee <small>(12%)</small></span><span>${money(c.fee)}</span></div><div class="cost-row total"><span>Estimated total</span><span>${money(c.total)}</span></div><p class="notice">Materials are excluded. No payment is collected. These are sample prices.</p></aside>`}
function bookingModal(){const m=modalState,p=pro(m.proId),d=m.draft;const steps=`<div class="step-progress">${['Your task','When and where','One last look'].map((s,i)=>`<span class="${m.step===i+1?'current':''}"><i>${i+1}</i>${s}</span>`).join('')}</div>`;const form=m.step===1?`<h3 style="font-size:25px;margin-bottom:24px">What needs doing?</h3><div class="field"><label for="booking-service">Your service</label><select id="booking-service" name="service">${p.skills.map(s=>`<option ${d.service===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label for="booking-hours">How much time should we allow?</label><select name="hours" id="booking-hours" data-booking-field="hours">${[1,1.5,2,2.5,3,4,5,6,8].map(n=>`<option value="${n}" ${Number(d.hours)===n?'selected':''}>${n} ${n===1?'hour':'hours'} · ${money(n*p.rate)} before service fee</option>`).join('')}</select><small>This is an estimate. Additional work needs agreement.</small></div><div class="field"><label for="booking-scope">A few details about the task</label><textarea id="booking-scope" name="scope" placeholder="What needs doing? Include anything helpful about supplies, stairs, or access." required minlength="10" maxlength="2000">${esc(d.scope)}</textarea></div><div class="field"><label for="booking-repeat">How often?</label><select id="booking-repeat" name="repeat">${['Once','Every week','Every two weeks','Every month'].map(r=>`<option ${d.repeat===r?'selected':''}>${r}</option>`).join('')}</select><small>Recurring choices save your preference for the first visit.</small></div>`:m.step===2?`<h3 style="font-size:25px;margin-bottom:24px">Make a little room.</h3><div class="field"><label for="booking-date">Choose a day</label><input id="booking-date" name="date" type="date" min="${addDate(p.today?0:1)}" max="${addDate(90)}" value="${d.date}" required></div><div class="field"><label for="booking-time">Start time</label><select id="booking-time" name="time">${p.availability.map(t=>`<option ${d.time===t?'selected':''}>${t}</option>`).join('')}</select><small>Times are in Austin local time. Availability is illustrative.</small></div><div class="field"><label for="booking-address">Where is the task?</label><input id="booking-address" name="address" value="${esc(d.address)}" placeholder="A sample Austin address" minlength="6" maxlength="200" required><small>Use a sample address for this product preview.</small></div>`:`<h3 style="font-size:25px;margin-bottom:10px">Everything look good?</h3>${[['Your task',d.service],['The plan',d.scope],['Time',`${dateLabel(d.date)} at ${d.time} · ${d.hours} hours`],['Place',d.address],['Frequency',d.repeat]].map(([l,v])=>`<div class="scope-summary"><small>${l}</small><span>${esc(v)}</span></div>`).join('')}<label class="check-field"><input type="checkbox" name="agreement" required><span>I understand this is a preview booking. No real person is hired and no payment is made.</span></label>`;openModal('A little help is on the way.',`${steps}<div class="booking-layout"><form data-form="booking" id="booking-form">${form}<p class="form-error" id="booking-error" role="alert"></p><div class="modal-actions">${m.step>1?button(icon('back')+' Back','booking-back','btn ghost'):button('Cancel','close-modal','btn ghost')}<button class="btn accent">${m.step===3?'Confirm preview booking':'Continue'} ${icon('arrow')}</button></div></form><div id="booking-summary">${bookingSummary(p,d)}</div></div>`)}
function confirmBooking(){const m=modalState,p=pro(m.proId),d=m.draft,c=costs(d,p);const booking={id:uid(),proId:p.id,...d,...c,hours:Number(d.hours),status:'upcoming',created:new Date().toISOString()};state.bookings.push(booking);ensureChat(p.id);state.messages[p.id].push({id:uid(),text:`Preview booking created: ${d.service}, ${dateLabel(d.date)} at ${d.time}. Estimated total ${money(c.total)}.`,from:'system',time:new Date().toISOString()});persist();modalState={type:'success',bookingId:booking.id};openModal('You’ve made a little more room.',`<div class="success-view"><div class="success-mark">${icon('check')}</div><h2>Your preview booking is ready.</h2><p>${esc(d.service)} with ${p.name}<br>${dateLabel(d.date)} at ${d.time}<br>${money(c.total)} estimated total</p><p style="margin-top:17px">No real person has been booked or contacted. You can now explore rescheduling, messages, and reviews.</p>${button('See your booking '+icon('arrow'),'success-booking','btn accent',`data-id="${booking.id}"`)}</div>`,true)}
function quoteModal(id){modalState={type:'quote',proId:id||null};openModal('Tell us what you have in mind.',`<p class="modal-subtitle">For projects that need a conversation first. Build a preview estimate request${pro(id)?' for '+pro(id).name:''}.</p><form data-form="quote"><div class="field"><label for="quote-service">What kind of help?</label><select name="service" id="quote-service">${(pro(id)?pro(id).skills:D.categories.flatMap(c=>c.sub)).map(s=>`<option>${s}</option>`).join('')}</select></div><div class="field"><label for="quote-scope">Describe your project</label><textarea name="scope" id="quote-scope" required minlength="15" maxlength="2000" placeholder="The scope, what you already have, and what a good result looks like."></textarea></div><div class="form-grid"><div class="field"><label for="quote-budget">Your estimated budget</label><input name="budget" id="quote-budget" type="number" min="25" max="100000" placeholder="250" required></div><div class="field"><label for="quote-date">Your preferred date</label><input name="date" id="quote-date" type="date" min="${today()}" max="${addDate(180)}" value="${addDate(3)}" required></div></div><div class="field"><label for="quote-address">Austin neighborhood or sample address</label><input name="address" id="quote-address" value="${esc(state.account.area)}" minlength="3" maxlength="200" required></div><button class="btn accent wide">Save preview request ${icon('arrow')}</button><p class="notice">This request is saved to My bookings. It is not sent to any person.</p></form>`,true)}
function jobModal(id){const b=state.bookings.find(x=>x.id===id);if(!b)return;const p=pro(b.proId);modalState={type:'job',id};openModal('Your task, all together.',`<span class="tag">${bookingStatus(b)} · Preview</span><h3 style="font-size:30px;margin:17px 0 9px">${esc(b.service)}</h3><p style="font-size:13px">${p?`With ${p.name} · `:''}${dateLabel(b.date)}${b.time?' at '+b.time:''}</p>${[['Task details',b.scope],['Location',b.address],['Estimate',isQuote(b)?`${money(b.budget)} budget. A final price has not been agreed.`:`${b.hours} hours · ${money(b.subtotal)} task subtotal + ${money(b.fee)} service fee = ${money(b.total)} estimated total`]].map(([l,v])=>`<div class="scope-summary"><small>${l}</small><span>${esc(v)}</span></div>`).join('')}<div class="timeline"><div class="timeline-item"><i>✓</i><div>Preview ${isQuote(b)?'request':'booking'} created<small>${new Date(b.created).toLocaleDateString('en-US',{month:'short',day:'numeric'})}</small></div></div>${b.rescheduled?`<div class="timeline-item"><i>✓</i><div>Schedule updated<small>${dateLabel(b.date)} ${b.time||''}</small></div></div>`:''}<div class="timeline-item"><i>${b.status==='completed'?'✓':'•'}</i><div>${b.status==='completed'?'Marked complete in preview':b.status==='canceled'?'Canceled in preview':'No real provider has been contacted'}<small>All activity is illustrative</small></div></div></div><div class="inline-actions">${p?button(icon('chat')+' Message','message','btn',`data-id="${p.id}"`):''}${b.status==='upcoming'?button('Reschedule','reschedule','btn soft',`data-id="${id}"`)+button('Mark complete','complete','text-link',`data-id="${id}"`):''}${['upcoming','requested'].includes(b.status)?button('Cancel booking','cancel-job','text-link text-danger',`data-id="${id}"`):''}${b.status==='completed'&&p?button('Book again','rebook','btn soft',`data-id="${id}"`)+button(state.reviews.some(r=>r.bookingId===id)?'Review saved':'Leave a review','review','text-link',`data-id="${id}"`):''}</div>`,true)}
function rescheduleModal(id){const b=state.bookings.find(x=>x.id===id);if(!b)return;const p=pro(b.proId);modalState={type:'reschedule',id};openModal('Find a better time.',`<p class="modal-subtitle">${esc(b.service)} with ${p.name}</p><form data-form="reschedule"><div class="field"><label for="reschedule-date">New date</label><input id="reschedule-date" name="date" type="date" min="${today()}" max="${addDate(90)}" value="${b.date}" required></div><div class="field"><label for="reschedule-time">Start time</label><select id="reschedule-time" name="time">${p.availability.map(t=>`<option ${b.time===t?'selected':''}>${t}</option>`).join('')}</select></div><button class="btn accent wide">Update preview booking</button><p class="notice">This updates your saved preview. No notification is sent.</p></form>`,true)}
function reviewModal(id){const b=state.bookings.find(x=>x.id===id);const old=state.reviews.find(r=>r.bookingId===id);modalState={type:'review',id,rating:old?.rating||5};openModal('A little thanks goes a long way.',`<p class="modal-subtitle">How was your sample ${esc(b.service.toLowerCase())} experience?</p><form data-form="review"><div class="review-stars" role="group" aria-label="Rating">${[1,2,3,4,5].map(n=>button('★','review-star',n<=modalState.rating?'chosen':'',`data-id="${n}" aria-label="${n} stars" aria-pressed="${n===modalState.rating}"`)).join('')}</div><div class="field"><label for="review-text">What would you like to share?</label><textarea id="review-text" name="text" minlength="10" maxlength="1500" required placeholder="A few details about the work and the experience.">${esc(old?.text||'')}</textarea></div><button class="btn wide">Save preview review</button><p class="notice">Your review stays in this browser and does not change a real person’s rating.</p></form>`,true)}
function locationModal(){modalState={type:'location'};openModal('Keep it local.',`<p class="modal-subtitle">The first Goodfolk concept explores Austin. Choose your neighborhood to personalize your profile and new estimate requests.</p><form data-form="location"><div class="field"><label for="location-area">Your neighborhood</label><select id="location-area" name="area">${['East Austin','South Lamar','North Loop','Hyde Park','Cherrywood','Bouldin Creek','Mueller','Zilker','Crestview','Other Austin neighborhood'].map(a=>`<option ${a===state.account.area?'selected':''}>${a}</option>`).join('')}</select></div><div class="field"><label for="location-zip">ZIP code</label><input name="zip" id="location-zip" value="${esc(state.account.zip)}" pattern="[0-9]{5}" inputmode="numeric" required maxlength="5"></div><button class="btn wide">Save your neighborhood</button><p class="notice">Distances and map locations are illustrative. Changing your neighborhood does not calculate new travel distances.</p></form>`,true)}
function confirmDialog(title,copy,action,id){modalState={type:'confirm',id};openModal(title,`<p style="font-size:13px;line-height:1.8">${copy}</p><div class="modal-actions">${button('Keep it','close-modal','btn soft')}${button('Yes, continue',action,'btn',`data-id="${id||''}"`)}</div>`,true)}
async function credits(){modalState={type:'credits'};let body='<p>Service photography courtesy of Unsplash. Photos illustrate services and do not depict the sample providers.</p>';try{const r=await fetch('assets/sources.json');const d=await r.json();body+=`<p class="notice">${Object.values(d).length} photo references in this project.</p><a class="text-link" href="assets/sources.json" target="_blank" rel="noopener">View full image sources ${icon('arrow')}</a>`}catch(e){body+=`<a href="https://unsplash.com" target="_blank" rel="noopener" class="text-link">Explore Unsplash</a>`}openModal('The people behind the pictures.',body,true)}
function preserveBookingForm(){const f=$('#booking-form');if(!f||modalState?.type!=='booking')return;const data=new FormData(f);for(const [k,v]of data.entries())if(k!=='agreement')modalState.draft[k]=v}
function chooseService(value){query=value;category='all';maxPrice=0;available=false;nav('explore')}
document.addEventListener('click',e=>{if(e.target.closest('.skip-link')){e.preventDefault();$('#main').focus();return}const a=e.target.closest('[data-action]');if(!a)return;const action=a.dataset.action,id=a.dataset.id,value=a.dataset.value;if(!$('.modal'))focusReturn=a;switch(action){
case 'category': category=id;query='';maxPrice=0;available=false;nav('explore');break;
case 'service': chooseService(value);break;
case 'profile': nav('profile/'+id);break;
case 'save':{const exists=state.saved.includes(id);state.saved=exists?state.saved.filter(x=>x!==id):[...state.saved,id];persist();render();toast(exists?'Removed from Your people.':'Saved to Your people.');break}
case 'today':available=!available;render();break;
case 'clear-filters':maxPrice=0;available=false;sort='recommended';render();break;
case 'clear-all':query='';category='all';maxPrice=0;available=false;sort='recommended';render();break;
case 'map':showMap=!showMap;render();break;
case 'book':startBooking(id);break;
case 'book-service':startBooking(id,value);break;
case 'book-date':startBooking(id,null,value);break;
case 'booking-back':preserveBookingForm();modalState.step--;bookingModal();break;
case 'close-modal':closeModal();break;
case 'close-link':closeModal(false);break;
case 'quote':quoteModal(id);break;
case 'preview':showPreview();break;
case 'location':locationModal();break;
case 'credits':credits();break;
case 'success-booking':closeModal(false);bookingTab='upcoming';if(location.hash==='#bookings'){render();jobModal(id)}else{nav('bookings');setTimeout(()=>jobModal(id),80)}break;
case 'job':jobModal(id);break;
case 'booking-tab':bookingTab=id;render();break;
case 'reschedule':rescheduleModal(id);break;
case 'cancel-job':confirmDialog('Cancel this preview booking?','It will move to Canceled in My bookings. Nothing is charged and no person is notified.','confirm-cancel',id);break;
case 'confirm-cancel':{const b=state.bookings.find(b=>b.id===id);if(b)b.status='canceled';persist();closeModal();render();toast('Preview booking canceled.');break}
case 'complete':{const b=state.bookings.find(b=>b.id===id);if(b)b.status='completed';persist();jobModal(id);render();toast('Marked complete in preview.');break}
case 'rebook':{const b=state.bookings.find(b=>b.id===id);if(b)startBooking(b.proId,b.service,null,b);break}
case 'review':reviewModal(id);break;
case 'review-star':modalState.rating=Number(id);$$('.review-stars button').forEach((b,i)=>{b.classList.toggle('chosen',i<Number(id));b.setAttribute('aria-pressed',String(i+1===Number(id)))});break;
case 'message':ensureChat(id);nav('messages/'+id);break;
case 'chat':chatId=id;render();break;
case 'provider-tab':providerTab=id;render();break;
case 'provider-edit':providerTab='profile';render();break;
case 'accept-lead':if(!state.provider.accepted.includes(id)){state.provider.accepted.push(id);persist();render();toast('Sample task added to your provider schedule.')}break;
case 'pass-lead':state.provider.hidden.push(id);persist();render();toast('Sample request passed.');break;
case 'release-lead':confirmDialog('Release this sample task?','It will return to your opportunities. No customer will be notified.','confirm-release',id);break;
case 'confirm-release':state.provider.accepted=state.provider.accepted.filter(x=>x!==id);persist();closeModal();render();toast('Sample task returned to opportunities.');break;
case 'reset-leads':state.provider.accepted=[];state.provider.hidden=[];persist();render();break;
case 'availability':{const n=Number(id);state.provider.days=state.provider.days.includes(n)?state.provider.days.filter(x=>x!==n):[...state.provider.days,n];persist();render();toast('Weekly availability saved.');break}
case 'toggle-updates':state.account.updates=!state.account.updates;persist();render();break;
case 'reset-preview':confirmDialog('Start fresh?','This removes your saved people, preview bookings, messages, reviews, provider draft, and account preferences from this browser.','confirm-reset');break;
case 'confirm-reset':try{localStorage.removeItem('goodfolk.v1')}catch(e){}location.reload();break;
}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.filter==='price'){maxPrice=Number(el.value);render()}if(el.dataset.filter==='sort'){sort=el.value;render()}if(el.dataset.bookingField==='hours'){preserveBookingForm();$('#booking-summary').innerHTML=bookingSummary(pro(modalState.proId),modalState.draft)}});
document.addEventListener('submit',e=>{const f=e.target;if(!f.dataset.form)return;e.preventDefault();if(!f.reportValidity())return;const v=Object.fromEntries(new FormData(f));switch(f.dataset.form){
case 'search':query=v.query.trim();category='all';available=/\btoday\b/i.test(query);nav('explore');break;
case 'booking':{preserveBookingForm();const m=modalState,d=m.draft;if(m.step===1&&(d.scope.trim().length<10||Number(d.hours)<1||Number(d.hours)>8)){$('#booking-error').textContent='Add a few more task details and choose a duration.';return}if(m.step===2&&(d.date<addDate(pro(m.proId).today?0:1)||d.date>addDate(90)||d.address.trim().length<6)){$('#booking-error').textContent='Choose a future available day and add a sample address.';return}if(m.step===3){confirmBooking()}else{m.step++;bookingModal()}break}
case 'quote':{if(v.date<today()||Number(v.budget)<25)return;state.bookings.push({id:uid(),proId:modalState.proId,service:v.service,scope:v.scope.trim(),budget:Number(v.budget),date:v.date,address:v.address.trim(),status:'requested',created:new Date().toISOString()});persist();closeModal();bookingTab='upcoming';nav('bookings');toast('Preview estimate request saved. Nothing was sent.');break}
case 'reschedule':{const b=state.bookings.find(x=>x.id===modalState.id);if(!b||v.date<today()||v.date>addDate(90))return;b.date=v.date;b.time=v.time;b.rescheduled=true;persist();jobModal(b.id);render();toast('Preview booking rescheduled.');break}
case 'review':{const old=state.reviews.findIndex(r=>r.bookingId===modalState.id);const r={bookingId:modalState.id,rating:modalState.rating,text:v.text.trim(),created:new Date().toISOString()};if(old>=0)state.reviews[old]=r;else state.reviews.push(r);persist();closeModal();render();toast('Your preview review is saved.');break}
case 'chat':{if(!v.message.trim()||!chatId)return;state.messages[chatId].push({id:uid(),text:v.message.trim(),from:'me',time:new Date().toISOString()});persist();render();$('#message-input')?.focus();break}
case 'location':state.account.area=v.area;state.account.zip=v.zip;persist();closeModal();render();toast('Your neighborhood is saved.');break;
case 'account':state.account={...state.account,name:v.name.trim(),email:v.email.trim(),area:v.area,zip:v.zip};persist();render();toast('Your details are saved for this browser.');break;
case 'provider':state.provider={...state.provider,name:v.name.trim(),category:v.category,rate:Number(v.rate),bio:v.bio.trim(),radius:Number(v.radius),applied:true};persist();render();toast('Your provider profile draft is saved.');break;
case 'availability':if(v.start>=v.end){$('#availability-error').textContent='Choose a finish time after your start time.';return}state.provider.start=v.start;state.provider.end=v.end;persist();toast('Working hours saved.');$('#availability-error').textContent='';break;
case 'earnings':{const weekly=Number(v.hours)*Number(v.rate);$('#earnings-output').textContent=`${money(weekly)} weekly gross task value. About ${money(weekly*4)} over four weeks, before expenses and taxes. This assumes every planned hour is booked and paid; it is not an earnings promise.`;break}
}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('.modal'))closeModal();if((e.key==='Enter'||e.key===' ')&&e.target.matches('.map-pin')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}if(e.key==='Tab'&&$('.modal')){const focusable=[...$('.modal').querySelectorAll('button:not([disabled]),a[href],input:not([disabled]),select,textarea,[tabindex="0"]')];const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
window.addEventListener('hashchange',route);
window.addEventListener('storage',e=>{if(e.key==='goodfolk.v1')toast('Preview activity changed in another tab. Refresh to see the latest version.')});
route();
})();
